            return blockColor;
        }
    #endif

    if (eyeDirection.y > 0.0) {  // Over horizon
        float view_y_inv = 1.0 / eyeDirection.y;

        float plane_distance_inf = (CLOUD_PLANE - base_pos.y) * view_y_inv;
